    image_patch = ImagePatch(image)
    hot_dog_patches = image_patch.find("hot dog")
    if not hot_dog_patches: return image_patch

    rows = {}
    for hd in hot_dog_patches:
        row = math.floor(hd.vertical_center / 100)  # Assuming each row has a height of 100 pixels
        if row not in rows:
            rows[row] = []
        rows[row].append(hd)

    valid_rows = [row for row in rows.values() if len(row) > 2]
    if not valid_rows: return image_patch

    min_distance = float('inf')
    closest_hot_dog = None
    for row in valid_rows:
        row.sort(key=lambda hd: hd.horizontal_center)
        for i in range(1, len(row) - 1):
            dist = abs(row[i].horizontal_center - row[i-1].horizontal_center) + abs(row[i].horizontal_center - row[i+1].horizontal_center)
            if dist < min_distance:
                min_distance = dist
                closest_hot_dog = row[i]

    return closest_hot_dog

